import React from "react";
import { useCart } from "../components/CartContext";

const Cart = () => {
  const { cartItems } = useCart();

  return (
    <div style={{ padding: "40px" }}>
      <h2>Your Cart 🛒</h2>
      {cartItems.length === 0 ? (
        <p>No items in the cart.</p>
      ) : (
        <ul>
          {cartItems.map((item, index) => (
            <li key={index}>
              <strong>{item.name}</strong> - ₹{item.price}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Cart;
